alter table public.vehicle_visual_identities add column if not exists artwork_review_status text; alter table public.vehicle_visual_identities add column if not exists artwork_review_note text; alter table public.vehicle_visual_identities add constraint vehicle_visual_identities_artwork_review_status_check check (artwork_review_status is null or artwork_review_status in ('exact_png_confirmed','missing_exact_png','needs_visual_comparison')); comment on column public.vehicle_visual_identities.artwork_review_status is 'Artwork audit only; does not change verified vehicle identity, and missing_exact_png means no verified exact PNG mapped in repository, not that no generic stock PNG exists.'
